function action(selection) {
    var text = (selection || "")
        .replace(/\r\n?/g, "\n")
        .replace(/[\u0085\u000b\u000c\u2028]/g, "\n")
        .trim();
    var paragraphs = text.length > 0
        ? text.split(/\n\s*\n+|\u2029+/).filter(Boolean).length
        : 0;
    return paragraphs + (paragraphs === 1 ? " paragraph" : " paragraphs");
}
